begin;
reset role;
insert into auth.users(id,email) values('00000000-0000-0000-0000-0000000000a1','pro1@example.com'),('00000000-0000-0000-0000-0000000000a2','pro2@example.com');
select t.as_user('00000000-0000-0000-0000-0000000000a1');
set role authenticated;
insert into public.agent_proactive_settings(user_id,weekly_recap_dow,time_zone,watches) values('00000000-0000-0000-0000-0000000000a1',5,'America/Los_Angeles','[{"kind":"balance_below","account":"checking","threshold_cents":50000}]');
select t.ok((select weekly_recap_dow=5 and quiet_start=22 and alerts from public.agent_proactive_settings),'the owner saves settings; defaults fill the rest (alerts on, quiet from 10 p.m.)');
update public.agent_proactive_settings set morning_brief=true where user_id='00000000-0000-0000-0000-0000000000a1';
select t.ok((select morning_brief from public.agent_proactive_settings),'the owner changes their own settings');
select t.must_fail($$insert into public.agent_proactive_settings(user_id) values('00000000-0000-0000-0000-0000000000a2')$$,'row-level security','a user cannot write another person''s settings');
select t.must_fail($$update public.agent_proactive_settings set watches='[{"note":"ssn 123456789"}]'$$,'check constraint','an identity number is refused by the table itself');
select t.must_fail($$update public.agent_proactive_settings set weekly_recap_dow=7$$,'check constraint','a weekday is 0 to 6');
update public.agent_proactive_settings set pending_offer='{"kind":"cancel_trial","merchant":"Paramount+","ends_on":"2026-10-13"}' where user_id='00000000-0000-0000-0000-0000000000a1';
select t.ok((select pending_offer->>'merchant'='Paramount+' from public.agent_proactive_settings),'an offer waits on the person''s own row');
select t.must_fail($$update public.agent_proactive_settings set pending_offer='[1]'$$,'check constraint','an offer is an object');
select t.must_fail($$update public.agent_proactive_settings set time_zone='x; drop table'$$,'check constraint','a time zone is a zone name');
select t.must_fail($$insert into public.agent_proactive_log(user_id,key,kind) values('00000000-0000-0000-0000-0000000000a1','x','finding')$$,'permission denied','a person cannot write their own delivery log');
reset role;
insert into public.agent_proactive_log(user_id,key,kind,capability_id,cadence) values('00000000-0000-0000-0000-0000000000a1','recap:2026-W41','weekly_recap','ANL-020',true);
select t.must_fail($$insert into public.agent_proactive_log(user_id,key,kind) values('00000000-0000-0000-0000-0000000000a1','recap:2026-W41','weekly_recap')$$,'duplicate key','a message key is delivered once per person, ever');
insert into public.agent_proactive_log(user_id,key,kind) values('00000000-0000-0000-0000-0000000000a2','recap:2026-W41','weekly_recap');
select t.ok((select count(*)=2 from public.agent_proactive_log),'the same key for another person is their own message');
select t.must_fail($$insert into public.agent_proactive_log(user_id,key,kind) values('00000000-0000-0000-0000-0000000000a1','k2','sms_blast')$$,'check constraint','only the known kinds are logged');
select t.as_user('00000000-0000-0000-0000-0000000000a2');
set role authenticated;
select t.ok((select count(*)=1 from public.agent_proactive_log),'a person reads only their own log');
select t.ok((select count(*)=0 from public.agent_proactive_settings),'and not another person''s settings');
reset role;
select t.as_user('');
set role anon;
select t.must_fail($$select * from public.agent_proactive_settings$$,'permission denied','anonymous callers read nothing');
reset role;
delete from auth.users where id='00000000-0000-0000-0000-0000000000a1';
select t.ok((select count(*)=0 from public.agent_proactive_settings) and (select count(*)=1 from public.agent_proactive_log),'deleting the account deletes its settings and log');
rollback;
